-- Store departments, per-breed Foundation inventory, optional feed development,
-- equipment-only tack, activity-based Wellness, and continuous 28-day horse years.

-- Preserve every existing horse's displayed age while changing to the authoritative rate.
update public.horses set birth_date=now()-(interval '28 days'*(greatest(0,extract(epoch from(now()-birth_date))/86400*30/365.25)));
create table if not exists public.horse_game_config(
 id boolean primary key default true check(id),real_days_per_horse_year numeric not null default 28 check(real_days_per_horse_year>0),
 wellness_max integer not null default 100,readiness_health_weight numeric not null default .34,readiness_hooves_weight numeric not null default .33,readiness_recovery_weight numeric not null default .33,
 training_recovery_wear integer not null default 3,show_recovery_wear integer not null default 5,show_hoof_wear integer not null default 2,
 passive_recovery_per_real_day numeric not null default 8,very_poor_threshold integer not null default 25,poor_threshold integer not null default 45,fair_threshold integer not null default 65,good_threshold integer not null default 85
);
insert into public.horse_game_config(id) values(true) on conflict(id) do nothing;
create or replace function public.horse_game_age(p_birth timestamptz,p_at timestamptz default now()) returns numeric language sql stable as $$
 select greatest(0,extract(epoch from(p_at-p_birth))/86400/(select real_days_per_horse_year from public.horse_game_config where id=true))
$$;

alter table public.foundation_breeds add column if not exists store_inventory_size integer not null default 4 check(store_inventory_size between 1 and 12);
alter table public.foundation_breeds add column if not exists store_price integer check(store_price is null or store_price>=0);
alter table public.foundation_breeds add column if not exists store_rotation_minutes integer check(store_rotation_minutes between 15 and 1440);
alter table public.store_settings drop constraint if exists store_settings_inventory_size_check;
alter table public.store_settings alter column inventory_size set default 4;
update public.store_settings set inventory_size=4,foundation_price=1000,rotation_minutes=60 where singleton;
alter table public.store_settings add constraint store_settings_inventory_size_check check(inventory_size between 1 and 12);

create or replace function public.refresh_store_inventory() returns void language plpgsql security definer set search_path=public as $$
declare cfg store_settings;b foundation_breeds;active_count integer;oldest timestamptz;rotation timestamptz;horse uuid;i integer;target integer;minutes integer;price integer;begin
 perform pg_advisory_xact_lock(674381);select * into cfg from store_settings where singleton;
 for b in select * from foundation_breeds where active order by sort_order loop
  target:=coalesce(b.store_inventory_size,cfg.inventory_size);minutes:=coalesce(b.store_rotation_minutes,cfg.rotation_minutes);price:=coalesce(b.store_price,cfg.foundation_price);
  select count(*),min(si.generated_at) into active_count,oldest from store_inventory si join horses h on h.id=si.horse_id where si.status='active' and h.breed=b.name;
  if active_count=0 or oldest<=now()-make_interval(mins=>minutes) then update store_inventory si set status='expired' from horses h where h.id=si.horse_id and si.status='active' and h.breed=b.name;active_count:=0;rotation:=now();else select max(si.rotation_key) into rotation from store_inventory si join horses h on h.id=si.horse_id where si.status='active' and h.breed=b.name;end if;
  if active_count<target then for i in active_count+1..target loop horse:=generate_store_horse(coalesce(rotation,now()),b.name);insert into store_inventory(horse_id,price,rotation_key) values(horse,price,coalesce(rotation,now()));end loop;end if;
 end loop;
end$$;
create or replace function public.get_store_inventory(p_breed text default null)
returns table(inventory_id uuid,horse_id uuid,name text,breed text,sex horse_sex,color text,birth_date timestamptz,stats jsonb,image_url text,mature_height_hands numeric,price integer,generated_at timestamptz,rotation_key timestamptz)
language plpgsql security definer set search_path=public as $$begin perform refresh_store_inventory();return query select si.id,h.id,h.name,h.breed,h.sex,h.color,h.birth_date,h.stats,h.image_url,h.mature_height_hands,si.price,si.generated_at,si.rotation_key from store_inventory si join horses h on h.id=si.horse_id where si.status='active' and(p_breed is null or h.breed=p_breed) order by h.breed,si.generated_at,h.name;end$$;
drop function if exists public.get_store_inventory();
create function public.get_store_inventory() returns table(inventory_id uuid,horse_id uuid,name text,breed text,sex horse_sex,color text,birth_date timestamptz,stats jsonb,image_url text,mature_height_hands numeric,price integer,generated_at timestamptz,rotation_key timestamptz) language sql security definer set search_path=public as $$select * from get_store_inventory(null)$$;

create table public.store_products(
 id text primary key,department text not null check(department in('feed','tack','stable_supplies')),name text not null,description text not null default '',price integer not null check(price>=0),active boolean not null default true,
 feed_success_probability numeric check(feed_success_probability between 0 and 1),development_min integer,development_max integer,eligible_stats text[],
 tack_slot text check(tack_slot in('bridle','saddle','saddle_pad','leg_protection')),quality text,tack_bonuses jsonb not null default '{}',discipline_orientation text[] not null default '{}',sort_order integer not null default 0,
 check(development_min is null or development_max>=development_min)
);
